class Server {
  constructor() {
    this.routes = new Map();
    this.middleware = null;
  }

  use(middleware) {
    this.middleware = middleware;
  }

  route(path, handler) {
    this.routes.set(path, handler);
  }

  handleRequest(req) {
    const res = { status: 200, body: null, headers: {} };
    const handler = this.routes.get(req.path);
    if (!handler) {
      res.status = 404;
      res.body = 'Not Found';
      return res;
    }
    // TODO: run middleware pipeline before handler
    handler(req, res);
    return res;
  }
}

module.exports = { Server };

