const assert = require('assert');
let passed = 0, failed = 0;
function runTest(name, fn) { try { fn(); passed++; console.log('PASS: ' + name); } catch(e) { failed++; console.log('FAIL: ' + name + ' \u2014 ' + e.message); } }

// Pipeline
runTest('pipeline exists', () => { const { Pipeline } = require('../middleware/pipeline'); assert.ok(Pipeline); });
runTest('pipeline chains middleware', () => {
  const { Pipeline } = require('../middleware/pipeline');
  const p = new Pipeline();
  const log = [];
  p.add((req, res, next) => { log.push('a'); next(); });
  p.add((req, res, next) => { log.push('b'); next(); });
  const req = {}, res = {};
  p.execute(req, res, () => { log.push('done'); });
  assert.deepStrictEqual(log, ['a', 'b', 'done']);
});
runTest('pipeline stops on no next', () => {
  const { Pipeline } = require('../middleware/pipeline');
  const p = new Pipeline();
  const log = [];
  p.add((req, res, next) => { log.push('a'); });
  p.add((req, res, next) => { log.push('b'); next(); });
  const req = {}, res = {};
  p.execute(req, res, () => { log.push('done'); });
  assert.deepStrictEqual(log, ['a']);
});

// Auth middleware
runTest('auth rejects missing token', () => {
  const { createAuth } = require('../middleware/auth');
  const auth = createAuth('secret123');
  const req = { headers: {} };
  const res = { status: 200, body: null };
  let nextCalled = false;
  auth(req, res, () => { nextCalled = true; });
  assert.strictEqual(res.status, 401);
  assert.strictEqual(nextCalled, false);
});
runTest('auth passes valid token', () => {
  const { createAuth } = require('../middleware/auth');
  const auth = createAuth('secret123');
  const req = { headers: { token: 'secret123' } };
  const res = { status: 200, body: null };
  let nextCalled = false;
  auth(req, res, () => { nextCalled = true; });
  assert.strictEqual(nextCalled, true);
  assert.strictEqual(res.status, 200);
});

// Rate limiter
runTest('ratelimit allows under limit', () => {
  const { createRateLimit } = require('../middleware/ratelimit');
  const limiter = createRateLimit(3);
  const req = { ip: '1.2.3.4' };
  const res = { status: 200 };
  let count = 0;
  limiter(req, res, () => { count++; });
  limiter(req, res, () => { count++; });
  limiter(req, res, () => { count++; });
  assert.strictEqual(count, 3);
});
runTest('ratelimit blocks over limit', () => {
  const { createRateLimit } = require('../middleware/ratelimit');
  const limiter = createRateLimit(2);
  const req = { ip: '5.6.7.8' };
  const res = { status: 200 };
  let count = 0;
  limiter(req, res, () => { count++; });
  limiter(req, res, () => { count++; });
  limiter(req, res, () => { count++; });
  assert.strictEqual(count, 2);
  assert.strictEqual(res.status, 429);
});

// Transform
runTest('transform uppercases body', () => {
  const { createTransform } = require('../middleware/transform');
  const transform = createTransform();
  const req = { body: 'hello world' };
  const res = {};
  let nextCalled = false;
  transform(req, res, () => { nextCalled = true; });
  assert.strictEqual(req.body, 'HELLO WORLD');
  assert.strictEqual(nextCalled, true);
});
runTest('transform handles non-string body', () => {
  const { createTransform } = require('../middleware/transform');
  const transform = createTransform();
  const req = { body: 42 };
  const res = {};
  let nextCalled = false;
  transform(req, res, () => { nextCalled = true; });
  assert.strictEqual(req.body, 42);
  assert.strictEqual(nextCalled, true);
});

// Integration: createPipeline factory
runTest('createPipeline returns pipeline', () => {
  const { createPipeline } = require('../middleware/index');
  const pipeline = createPipeline({ token: 'abc', rateLimit: 5 });
  assert.ok(pipeline);
  assert.ok(typeof pipeline.execute === 'function');
});
runTest('full pipeline auth->rate->transform', () => {
  const { createPipeline } = require('../middleware/index');
  const pipeline = createPipeline({ token: 'mytoken', rateLimit: 10 });
  const req = { headers: { token: 'mytoken' }, body: 'test data', ip: '10.0.0.1' };
  const res = { status: 200, body: null };
  let handlerCalled = false;
  pipeline.execute(req, res, () => { handlerCalled = true; });
  assert.strictEqual(handlerCalled, true);
  assert.strictEqual(req.body, 'TEST DATA');
});
runTest('full pipeline rejects bad auth', () => {
  const { createPipeline } = require('../middleware/index');
  const pipeline = createPipeline({ token: 'mytoken', rateLimit: 10 });
  const req = { headers: { token: 'wrong' }, body: 'test', ip: '10.0.0.2' };
  const res = { status: 200, body: null };
  let handlerCalled = false;
  pipeline.execute(req, res, () => { handlerCalled = true; });
  assert.strictEqual(handlerCalled, false);
  assert.strictEqual(res.status, 401);
});

// Server integration
runTest('server uses pipeline', () => {
  const { Server } = require('../server');
  const { createPipeline } = require('../middleware/index');
  const server = new Server();
  const pipeline = createPipeline({ token: 'srvtoken', rateLimit: 100 });
  server.use((req, res, next) => { pipeline.execute(req, res, next); });
  server.route('/echo', (req, res) => { res.body = req.body; });
  const res = server.handleRequest({ path: '/echo', headers: { token: 'srvtoken' }, body: 'hello', ip: '10.0.0.3' });
  assert.strictEqual(res.body, 'HELLO');
  assert.strictEqual(res.status, 200);
});
runTest('server pipeline blocks unauthorized', () => {
  const { Server } = require('../server');
  const { createPipeline } = require('../middleware/index');
  const server = new Server();
  const pipeline = createPipeline({ token: 'srvtoken', rateLimit: 100 });
  server.use((req, res, next) => { pipeline.execute(req, res, next); });
  server.route('/echo', (req, res) => { res.body = req.body; });
  const res = server.handleRequest({ path: '/echo', headers: {}, body: 'hello', ip: '10.0.0.4' });
  assert.strictEqual(res.status, 401);
  assert.strictEqual(res.body, null);
});

console.log('\n' + passed + '/' + (passed+failed) + ' tests passed');
if (failed > 0) process.exit(1);
